// Build ISC 11 Mathematics ch01 Sets. Run from platform/:
//   npx tsx content/authored/maths/isc-11-mathematics-ch01/src/build.mjs
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, table, flow, build, chapterTests } from './lib.mjs';
import { range, S, arr, un, it, df, cp, subset, same, filt, tex, subsets, iv, inIv, agrees, ivTex, venn, venn2, venn3, vennNested, fromRegions, allSubsets } from './sets.mjs';
import { numberLine } from './nl.mjs';

setUnit('isc-11-mathematics-ch01');
await import('./questions.mjs');
await import('./questions2.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n(?![a-z])/g, '\n');
const must = (cond, msg) => { if (!cond) throw new Error(`self-check failed: ${msg}`); };
const N = (a, b) => range(a, b);
const $ = (A) => `$${tex(A)}$`;
const prime = (x) => x > 1 && N(2, x - 1).every((p) => x % p);
const tick = (b) => (b ? '✓' : '✗');
const joined = (A) => arr(A).join();

// ================================================================ deck 1 visuals (Sets, subsets and intervals)
const dayStartT = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].filter((d) => d.startsWith('T'));
const mathLetters = S([...'MATHEMATICS']);
must(dayStartT.join() === 'Tuesday,Thursday' && mathLetters.size === 8, 'well-defined examples');
const wd = table(['Collection', 'Well defined?', 'Reason or listing'], [['Days of the week that begin with T', '✓', $(S(dayStartT))], ['The best songs of the decade', '✗', 'Opinion: no rule decides'], ['Distinct letters of the word MATHEMATICS', '✓', $(mathLetters)], ['The most interesting novels', '✗', 'Opinion: no rule decides']], 'Table of four collections. Days of the week beginning with T and the distinct letters of MATHEMATICS are well defined and can be listed; the best songs and the most interesting novels are opinions, so they are not sets.', 'A set needs a rule that settles membership.');

const rbRows = [
  [r`$\{x \in \mathbb{N} : x \text{ is a two-digit multiple of } 12\}$`, filt(S(N(10, 99)), (x) => x % 12 === 0)],
  [r`$\{x \in \mathbb{Z} : x^2 < 20\}$`, filt(S(N(-10, 10)), (x) => x * x < 20)],
  [r`$\{x \in \mathbb{N} : x \text{ divides } 28\}$`, filt(S(N(1, 60)), (x) => 28 % x === 0)],
  [r`$\{n(n + 1) : n \in \mathbb{N},\ n \le 4\}$`, S(N(1, 4).map((n) => n * (n + 1)))],
];
must(rbRows.map(([, A]) => joined(A)).join('|') === '12,24,36,48,60,72,84,96|-4,-3,-2,-1,0,1,2,3,4|1,2,4,7,14,28|2,6,12,20', 'roster rows');
const rbTable = table(['Set-builder form', 'Roster form', 'Elements'], rbRows.map(([b, A]) => [b, $(A), `$${A.size}$`]), 'Table converting four sets from set-builder to roster form: two-digit multiples of 12 give eight numbers from 12 to 96; integers whose square is below 20 give minus 4 to 4; divisors of 28 give six numbers; n times n plus 1 for n up to 4 gives 2, 6, 12, 20.', 'One set, two ways of writing it.');

const typeRows = [
  ['Empty', r`$\{x \in \mathbb{R} : x^2 + 4 = 0\}$`, filt(S(N(-30, 30)), (x) => x * x + 4 === 0)],
  ['Singleton', r`$\{x \in \mathbb{N} : 2x + 1 = 9\}$`, filt(S(N(1, 60)), (x) => 2 * x + 1 === 9)],
  ['Finite', r`$\{x \in \mathbb{N} : x \text{ is a cube below } 100\}$`, filt(S(N(1, 99)), (x) => Math.round(Math.cbrt(x)) ** 3 === x)],
];
must(typeRows.map(([, , A]) => A.size).join() === '0,1,4', 'type sizes');
const typesTable = table(['Type', 'Example', 'Number of elements'], [...typeRows.map(([t, e, A]) => [t, e, `$${A.size}$`]), ['Infinite', r`$\{x \in \mathbb{Z} : x < 5\}$`, 'counting never ends']], 'Table of the types of sets, one example each: an empty set with no element, a singleton with one element, a finite set of cubes below 100 with four elements, and an infinite set of integers below 5 that never ends.', 'Count the elements to decide the type.');

const base3 = S([2, 4, 6]);
const eqCand = [['$\\{6, 4, 2\\}$', S([6, 4, 2])], ['$\\{2, 2, 4, 6, 6\\}$', S([2, 2, 4, 6, 6])], [r`$\{x \in \mathbb{N} : x \text{ is even},\ x < 7\}$`, filt(S(N(1, 30)), (x) => x % 2 === 0 && x < 7)], [r`$\{x \in \mathbb{N} : x \text{ is even},\ x \le 8\}$`, filt(S(N(1, 30)), (x) => x % 2 === 0 && x <= 8)]];
const eqTable = table(['Description', 'Roster form, each element once', r`Equal to $\{2, 4, 6\}$?`], eqCand.map(([d, A]) => [d, $(A), tick(same(A, base3))]), 'Table testing four sets against 2, 4, 6: the same elements in another order, with repeats, or described as even numbers below 7 are all equal to it; even numbers up to 8 include the extra element 8, so that set is different.', 'Order and repeats do not matter; the elements do.');
must(eqCand.map(([, A]) => same(A, base3)).join() === 'true,true,true,false', 'equal-set table');

const nested = vennNested(S([2, 4, 6, 8, 10]), S([4, 8]), S(N(1, 10)), { mode: 'elems', alt: 'A Venn diagram inside a rectangle U of the numbers 1 to 10: a large circle A holds 2, 6, 10 and, inside it, a small circle B holds 4 and 8; the numbers 1, 3, 5, 7, 9 lie outside both circles.', caption: r`$B = \{4, 8\}$ lies inside $A = \{2, 4, 6, 8, 10\}$, so $B \subset A$.` });
must(joined(S(nested.regions['11'])) === '4,8' && joined(S(nested.regions['10'])) === '2,6,10' && joined(S(nested.regions['00'])) === '1,3,5,7,9', 'nested regions');

const pA = S(['p', 'q', 'r']);
const pSets = subsets(pA);
const powerTable = table(['Size', r`Subsets of $\{p, q, r\}$`, 'Count'], [0, 1, 2, 3].map((k) => { const L = pSets.filter((x) => x.length === k); return [`$${k}$`, L.map((x) => `$${x.length ? `\\{${x.join(', ')}\\}` : '\\varnothing'}$`).join(' '), `$${L.length}$`]; }), 'Table listing all 8 subsets of p, q, r by size: one of size 0, the empty set; three of size 1; three of size 2; and one of size 3, the set itself. The counts 1, 3, 3, 1 add up to 8.', r`Total: $1 + 3 + 3 + 1 = 8 = 2^3$.`);
must(pSets.length === 8 && pSets.map((x) => x.length).join('') === '01112223', 'power set sizes');
const powCount = table(['$n(A)$', ...N(0, 6).map((n) => `$${n}$`)], [['Subsets', ...N(0, 6).map((n) => `$${subsets(S(N(1, n))).length}$`)], ['Proper subsets', ...N(0, 6).map((n) => `$${Math.max(subsets(S(N(1, n))).length - 1, 0)}$`)]], 'Table of the number of subsets of a set with 0 to 6 elements: 1, 2, 4, 8, 16, 32, 64, doubling each time; the proper subsets are one fewer in each column.', r`Each new element doubles the count: $2^n$.`);
must(N(0, 6).map((n) => subsets(S(N(1, n))).length).join() === '1,2,4,8,16,32,64', 'doubling');

const univ = venn({ circles: [{ name: 'A', cx: 4.5, cy: 3, r: 2, set: S([3, 6, 9]) }], U: S(N(1, 9)), mode: 'elems', alt: 'A rectangle U holding the numbers 1 to 9 with one circle A around 3, 6 and 9; the remaining numbers 1, 2, 4, 5, 7 and 8 lie inside the rectangle but outside the circle.', caption: r`The universal set $U = \{1, 2, \dots, 9\}$ is the rectangle; $A$ is the circle of multiples of $3$.` });
must(joined(S(univ.regions['0'])) === '1,2,4,5,7,8', 'outside A');

const IV = { a: iv(-1, 4, false, false), b: iv(-1, 4), c: iv(-1, 4, false, true), d: iv(null, 4, false, true) };
const predI = { a: (x) => -1 < x && x < 4, b: (x) => -1 <= x && x <= 4, c: (x) => -1 < x && x <= 4, d: (x) => x <= 4 };
for (const k of 'abcd') must(agrees(predI[k], [IV[k]]), `interval ${k}`);
const nl1 = numberLine({ from: -3, to: 6, rows: [{ tag: '(-1, 4)', altTag: 'Row one, open interval', ivs: [IV.a] }, { tag: '[-1, 4]', altTag: 'Row two, closed interval', ivs: [IV.b] }, { tag: '(-1, 4]', altTag: 'Row three, half-open interval', ivs: [IV.c] }, { tag: '(-∞, 4]', altTag: 'Row four, unbounded interval', ivs: [IV.d] }] }, 'Open circles show excluded end points, filled circles show included ones, and an arrow shows that the set goes on for ever.', { lead: 'Four kinds of interval.' });
const ivTable = table(['Set-builder form', 'Interval', 'End points'], [[r`$\{x \in \mathbb{R} : -1 < x < 4\}$`, `$${ivTex(IV.a)}$`, 'both excluded'], [r`$\{x \in \mathbb{R} : -1 \le x \le 4\}$`, `$${ivTex(IV.b)}$`, 'both included'], [r`$\{x \in \mathbb{R} : -1 < x \le 4\}$`, `$${ivTex(IV.c)}$`, 'left out, right in'], [r`$\{x \in \mathbb{R} : x \le 4\}$`, `$${ivTex(IV.d)}$`, 'infinity is never included']], 'Table pairing four set-builder descriptions with interval notation: the open interval from minus 1 to 4, the closed interval, the half-open interval that includes 4, and the unbounded interval of numbers up to 4.', 'Round bracket: excluded. Square bracket: included.');
const chain = flow('LR', [['n', r`$\mathbb{N}$ natural`], ['w', r`$\mathbb{W}$ whole`], ['z', r`$\mathbb{Z}$ integers`], ['q', r`$\mathbb{Q}$ rationals`], ['r', r`$\mathbb{R}$ reals`]], [['n', 'w', r`$\subset$`], ['w', 'z', r`$\subset$`], ['z', 'q', r`$\subset$`], ['q', 'r', r`$\subset$`]], 'Flow diagram of the number sets, each inside the next: natural numbers inside whole numbers inside integers inside rational numbers inside real numbers.', 'Each number set is a subset of the next.');
const ivRows = [iv(-1, 4, false, false), iv(-1, 4), iv(-1, 4, false, true)];
const ivInts = table(['Interval', 'Integers inside', 'Count'], ivRows.map((I) => { const L = N(-6, 7).filter((x) => inIv(I, x)); return [`$${ivTex(I)}$`, `$${L.join(', ')}$`, `$${L.length}$`]; }), 'Table counting the integers in three intervals with end points minus 1 and 4: the open interval holds 0 to 3, four integers; the closed interval holds minus 1 to 4, six integers; the interval that keeps only 4 holds 0 to 4, five integers.', 'The end points decide the count.');
must(ivInts.spec.rows.map((x) => x[2]).join() === '$4$,$6$,$5$', 'integer counts');
const summary1 = flow('LR', [['s', 'Set: a well-defined collection'], ['f', 'Roster, set-builder, interval'], ['t', 'Empty, finite, infinite, equal'], ['p', r`Subsets and power set: $2^n$`]], [['s', 'f'], ['f', 't'], ['t', 'p']], 'Summary flow: a set is a well-defined collection; write it in roster, set-builder or interval form; classify it as empty, finite, infinite or equal to another; a set of n elements has 2 to the power n subsets.', 'From a collection to its subsets.');

// worked-example data, deck 1
const ex1 = filt(S(N(-20, 20)), (x) => -5 < 3 * x - 2 && 3 * x - 2 <= 10);
must(joined(ex1) === '0,1,2,3,4', 'ex1 set');
const ex2A = filt(S(N(-30, 30)), (x) => x * x - 2 * x - 8 === 0), ex2B = filt(S(N(1, 30)), (x) => x * x - 2 * x - 8 === 0);
must(joined(ex2A) === '-2,4' && joined(ex2B) === '4', 'ex2 sets');
const ex3 = subsets(S(N(1, 6))).filter((a) => a.includes(2) && !a.includes(5)).length;
must(ex3 === 16, 'ex3 count');

// ================================================================ deck 2 visuals (operations, laws, counting)
const U12 = S(N(1, 12)), FA = S([1, 2, 3, 4, 6, 8, 12]), PB = S([2, 3, 5, 7, 11]);
must(joined(FA) === joined(filt(U12, (x) => 24 % x === 0)) && joined(PB) === joined(filt(U12, prime)), 'A factors of 24, B primes');
const vBase = venn2(FA, PB, U12, { mode: 'elems', names: ['A', 'B'], alt: 'A Venn diagram of U equal to 1 to 12 with two overlapping circles: A holds the factors of 24, which are 1, 2, 3, 4, 6, 8, 12, and B holds the primes 2, 3, 5, 7, 11. Only A has 1, 4, 6, 8, 12; the overlap has 2 and 3; only B has 5, 7, 11; 9 and 10 lie outside.', caption: r`$A$ = factors of $24$ and $B$ = primes, inside $U = \{1, \dots, 12\}$.` });
must(joined(S(vBase.regions['10'])) === '1,4,6,8,12' && joined(S(vBase.regions['11'])) === '2,3' && joined(S(vBase.regions['01'])) === '5,7,11' && joined(S(vBase.regions['00'])) === '9,10', 'base regions');
const SQ = S([1, 4, 9]), PR = S([2, 3, 5, 7]);
const vDisj = venn({ circles: [{ name: 'M', cx: 2.9, cy: 3, r: 1.5, set: SQ }, { name: 'P', cx: 6.1, cy: 3, r: 1.5, set: PR }], U: S(N(1, 10)), mode: 'elems', alt: 'A Venn diagram of U equal to 1 to 10 with two separate circles that do not touch: M holds the squares 1, 4, 9 and P holds the primes 2, 3, 5, 7. The numbers 6, 8 and 10 lie outside both. No number is in both circles.', caption: r`Disjoint sets: $M \cap P = \varnothing$.` });
must(it(SQ, PR).size === 0 && vDisj.regions['11'].length === 0 && joined(S(vDisj.regions['00'])) === '6,8,10', 'disjoint');
const vComp = venn({ circles: [{ name: 'A', cx: 4.5, cy: 3, r: 2, set: FA }], U: U12, mode: 'elems', alt: 'A rectangle U holding 1 to 12 with a circle A around the factors of 24: 1, 2, 3, 4, 6, 8, 12. The complement of A is everything in the rectangle outside the circle: 5, 7, 9, 10, 11.', caption: r`The complement $A' = U - A$ is everything outside the circle.` });
must(joined(S(vComp.regions['0'])) === joined(cp(U12, FA)) && cp(U12, FA).size === 5, 'complement');

const opRows = [[r`$A \cup B$`, un(FA, PB)], [r`$A \cap B$`, it(FA, PB)], [r`$A - B$`, df(FA, PB)], [r`$B - A$`, df(PB, FA)], [r`$A'$`, cp(U12, FA)], [r`$(A \cup B)'$`, cp(U12, un(FA, PB))], [r`$(A \cap B)'$`, cp(U12, it(FA, PB))]];
must(opRows.map(([, A]) => joined(A)).join('|') === '1,2,3,4,5,6,7,8,11,12|2,3|1,4,6,8,12|5,7,11|5,7,9,10,11|9,10|1,4,5,6,7,8,9,10,11,12', 'op rows');
const opTable = table(['Operation', 'Result', 'Elements'], opRows.map(([n, A]) => [n, $(A), `$${A.size}$`]), 'Table of seven operations on A and B inside U of 1 to 12: the union has 10 elements, the intersection 2, A minus B 5, B minus A 3, the complement of A 5, the complement of the union 2, and the complement of the intersection 10.', 'Each result is read from the regions.');

const S4 = allSubsets(4), U4 = S(N(1, 4));
const lawNames = [
  ['Commutative', r`$A \cup B = B \cup A$ and $A \cap B = B \cap A$`, (A, B) => same(un(A, B), un(B, A)) && same(it(A, B), it(B, A))],
  ['Associative', r`$(A \cup B) \cup C = A \cup (B \cup C)$`, (A, B, C) => same(un(un(A, B), C), un(A, un(B, C)))],
  ['Distributive', r`$A \cap (B \cup C) = (A \cap B) \cup (A \cap C)$`, (A, B, C) => same(it(A, un(B, C)), un(it(A, B), it(A, C)))],
  ['Distributive', r`$A \cup (B \cap C) = (A \cup B) \cap (A \cup C)$`, (A, B, C) => same(un(A, it(B, C)), it(un(A, B), un(A, C)))],
  ['De Morgan', r`$(A \cup B)' = A' \cap B'$`, (A, B) => same(cp(U4, un(A, B)), it(cp(U4, A), cp(U4, B)))],
  ['De Morgan', r`$(A \cap B)' = A' \cup B'$`, (A, B) => same(cp(U4, it(A, B)), un(cp(U4, A), cp(U4, B)))],
  ['Identity', r`$A \cup \varnothing = A$ and $A \cap U = A$`, (A) => same(un(A, S([])), A) && same(it(A, U4), A)],
  ['Complement', r`$A \cup A' = U$ and $A \cap A' = \varnothing$`, (A) => same(un(A, cp(U4, A)), U4) && it(A, cp(U4, A)).size === 0],
  ['Difference', r`$A - B = A \cap B'$`, (A, B) => same(df(A, B), it(A, cp(U4, B)))],
];
const lawOK = lawNames.map(([, , f]) => S4.every((A) => S4.every((B) => S4.every((C) => f(A, B, C)))));
must(lawOK.every(Boolean), 'laws on all 4096 triples');
const lawTable = table(['Law', 'Statement', r`Tested on every triple of subsets of $\{1, 2, 3, 4\}$`], lawNames.map(([n, s], i) => [n, s, tick(lawOK[i])]), 'Table of nine rules of set algebra: commutative, associative, two distributive laws, two De Morgan laws, identity, complement and difference, each with a tick showing it was tested on every triple of subsets of 1, 2, 3, 4.', 'Every rule passed the brute-force test.');
const regRows = [['Only $A$', true, false], ['Both', true, true], ['Only $B$', false, true], ['Neither', false, false]];
const regTable = table(['Region', 'In $A$', 'In $B$', r`In $(A \cup B)'$`, r`In $A' \cap B'$`], regRows.map(([n, p, o]) => [n, tick(p), tick(o), tick(!(p || o)), tick(!p && !o)]), 'Table of the four regions of a two-circle Venn diagram. Only the region outside both circles lies in the complement of the union, and only that region lies in both complements, so the two sets are the same.', 'The last two columns match in every row: De Morgan.');
must(regRows.every(([, p, o]) => !(p || o) === (!p && !o)), 'region table');

const tc = fromRegions({ a: 55, ab: 30, b: 42, none: 23 });
must(tc.U.size === 150 && tc.A.size === 85 && tc.B.size === 72 && it(tc.A, tc.B).size === 30 && un(tc.A, tc.B).size === 127, 'tea/coffee counts');
const vCount2 = venn2(tc.A, tc.B, tc.U, { mode: 'count', names: ['T', 'C'], alt: 'A Venn diagram of 150 people with two overlapping circles: T for tea with 85 people and C for coffee with 72. Only tea has 55, the overlap has 30, only coffee has 42, and 23 lie outside both circles.', caption: r`Region counts: $55 + 30 + 42 + 23 = 150$.` });
must(vCount2.regions['10'].length === 55 && vCount2.regions['11'].length === 30 && vCount2.regions['01'].length === 42 && vCount2.regions['00'].length === 23, 'count regions');
const three = fromRegions({ abc: 4, ab: 6, bc: 5, ac: 7, a: 12, b: 10, c: 9, none: 7 });
const t3 = [three.A.size, three.B.size, three.C.size, it(three.A, three.B).size, it(three.B, three.C).size, it(three.A, three.C).size, it(it(three.A, three.B), three.C).size];
must(t3.join() === '29,25,25,10,9,11,4' && three.U.size === 60, `three-set data ${t3}`);
const union3 = un(un(three.A, three.B), three.C);
must(29 + 25 + 25 - 10 - 9 - 11 + 4 === union3.size && union3.size === 53, 'three-set formula');
const vCount3 = venn3(three.A, three.B, three.C, three.U, { mode: 'count', names: ['A', 'B', 'C'], alt: 'A Venn diagram of 60 learners with three overlapping circles A, B and C. The centre holds 4; the pairwise-only regions hold 6, 5 and 7; the single-set regions hold 12, 10 and 9; 7 lie outside all three circles.', caption: r`The regions add to $60$; $n(A \cup B \cup C) = 53$.` });
must(vCount3.regions['111'].length === 4 && vCount3.regions['110'].length === 6 && vCount3.regions['011'].length === 5 && vCount3.regions['101'].length === 7 && vCount3.regions['100'].length === 12 && vCount3.regions['010'].length === 10 && vCount3.regions['001'].length === 9 && vCount3.regions['000'].length === 7, 'three regions');

const IA = iv(-5, 1, false, true), IB = iv(-2, 4, true, false);
const ia = (x) => inIv(IA, x), ib = (x) => inIv(IB, x);
const I_cap = iv(-2, 1), I_cup = iv(-5, 4, false, false), I_diff = iv(-5, -2, false, false), I_diff2 = iv(1, 4, false, false);
must(agrees((x) => ia(x) && ib(x), [I_cap]) && agrees((x) => ia(x) || ib(x), [I_cup]) && agrees((x) => ia(x) && !ib(x), [I_diff]) && agrees((x) => ib(x) && !ia(x), [I_diff2]), 'interval ops');
const nl2 = numberLine({ from: -6, to: 5, rows: [{ tag: 'A', ivs: [IA] }, { tag: 'B', ivs: [IB] }, { tag: 'A ∩ B', ivs: [I_cap] }, { tag: 'A ∪ B', ivs: [I_cup] }, { tag: 'A − B', ivs: [I_diff] }] }, 'Filled circles mark included end points and open circles mark excluded ones.', { lead: 'Operations on A equal to the interval from minus 5, open, to 1, closed, and B equal to the interval from minus 2, closed, to 4, open.' });
const summary2 = flow('LR', [['u', 'Union, intersection, difference, complement'], ['l', 'Laws: commutative, distributive, De Morgan'], ['c', r`$n(A \cup B) = n(A) + n(B) - n(A \cap B)$`], ['t', 'Three sets: singles, minus pairs, plus triple']], [['u', 'l'], ['l', 'c'], ['c', 't']], 'Summary flow: the four operations; the laws including De Morgan; the two-set counting formula; the three-set counting formula.', 'From operations to counting.');

// worked-example data, deck 2
const e2U = S(N(1, 12));
const e2L = cp(e2U, un(FA, PB)), e2R = it(cp(e2U, FA), cp(e2U, PB));
must(joined(e2L) === '9,10' && same(e2L, e2R), 'verify De Morgan example');
const wd2 = { teaOnly: df(tc.A, tc.B).size, neither: cp(tc.U, un(tc.A, tc.B)).size };
must(wd2.teaOnly === 55 && wd2.neither === 23, 'word problem');

// ================================================================ deck 1
const d1 = deck({
  part: 1, title: 'Sets — Part 1: Sets, subsets and intervals',
  goals: ['Decide when a collection is a set and write it in roster and set-builder form', 'Classify sets as empty, singleton, finite, infinite or equal', 'List subsets, count the power set and use the universal set', 'Write subsets of the real numbers in interval notation'],
  slides: [
    sl('title', 'Sets, Part 1: Collections with a clear rule', { b: 'A set is a collection whose membership is settled by a clear rule.', v: wd, n: 'Welcome to Class Eleven mathematics, the course that begins with sets. A set is a collection of objects together with a rule that decides, for every object, whether it belongs. The distinct letters of a word form a set. The best songs of the decade do not, because best is an opinion. In this part you will write sets in several ways, classify them, and count their subsets.' }),
    sl('concept', 'What you will be able to do', { ul: ['Tell a **well-defined** collection from an opinion', 'Write sets in **roster** and **set-builder** form', 'Classify **empty**, **singleton**, **finite**, **infinite** and **equal** sets', 'List **subsets** and count the **power set**', 'Write **intervals** of real numbers'], v: summary1, n: 'Here are your goals for part one. You will spot a genuine set, write it by listing or by a rule, and sort sets into types. Then you will study subsets and count them with a doubling rule. You will finish with intervals, the sets of real numbers that appear in nearly every later chapter of this course.' }),
    sl('concept', 'Elements and notation', { b: r`The objects of a set are its **elements**. Write $a \in A$ when $a$ belongs to $A$ and $a \notin A$ when it does not. Capital letters name sets. Five number sets have fixed names: $\mathbb{N}$, $\mathbb{W}$, $\mathbb{Z}$, $\mathbb{Q}$, $\mathbb{R}$.`, v: chain, m: [r`\mathbb{N} \subset \mathbb{W} \subset \mathbb{Z} \subset \mathbb{Q} \subset \mathbb{R}`], n: 'The objects in a set are called its elements. We use a rounded letter e symbol to say that an element belongs to a set, and the same symbol crossed out to say it does not. Capital letters name sets. Five number sets keep fixed names: natural numbers, whole numbers, integers, rational numbers and real numbers. Each one sits inside the next, as the chain shows.' }),
    sl('concept', 'Roster form and set-builder form', { b: r`**Roster form** lists the elements: $\{12, 24, 36\}$. **Set-builder form** states a rule: $\{x \in \mathbb{N} : x \text{ is a multiple of } 12,\ x < 40\}$. List each element once; order does not matter.`, v: rbTable, n: 'A set can be written in two ways. Roster form lists the elements between curly brackets. Set-builder form states the rule every element obeys, after a colon. The table converts four sets from rule to list. Look at the second row: the integers whose square is below twenty include negative numbers and zero, so always check which number system the rule lives in.' }),
    sl('check', 'Quick check: is it a set?', { b: 'Pick the collection that a clear rule defines.', chk: 'm01', v: wd, n: 'Look for the option where a clear rule decides membership for every object, with no opinion involved.' }),
    sl('example', 'Worked example 1: from rule to roster', { b: r`Write $A = \{x \in \mathbb{Z} : -5 < 3x - 2 \le 10\}$ in roster form and find $n(A)$.`, ul: [r`Add $2$ to every part: $-3 < 3x \le 12$`, r`Divide by $3$: $-1 < x \le 4$`, r`Integers in this range: $0, 1, 2, 3, 4$ ($-1$ is excluded)`, r`**Answer.** $A = \{0, 1, 2, 3, 4\}$, $n(A) = 5$`], v: table(['Step', 'Result'], [['Inequality', r`$-5 < 3x - 2 \le 10$`], [r`Solve for $x$`, r`$-1 < x \le 4$`], ['Integers in range', $(filt(S(N(-20, 20)), (x) => -5 < 3 * x - 2 && 3 * x - 2 <= 10))], ['Number of elements', `$${ex1.size}$`]], 'Table of the worked example: the inequality, its solution greater than minus 1 and at most 4, the integers 0, 1, 2, 3, 4 that satisfy it, and the count 5.', 'Solve first, then list the integers allowed.'), n: 'Treat the double inequality like an equation: add two to every part, then divide by three. The result says x is greater than minus one and at most four. Because minus one is not allowed, the integers start at zero and run up to four. Counting them gives five elements.' }),
    sl('concept', 'Types of sets', { b: r`**Empty set** $\varnothing$: no element. **Singleton**: one element. **Finite**: counting ends. **Infinite**: counting never ends. Note that $\{\varnothing\}$ is **not** empty; it has one element.`, v: typesTable, n: 'Sets are classified by size. The empty set has no elements and is written with a slashed circle. A singleton has exactly one. A finite set can be counted to the end, and an infinite set cannot. A common trap: a set whose only element is the empty set is not itself empty, because it has one element inside the brackets.' }),
    sl('concept', 'Equal sets', { b: r`$A = B$ when they have exactly the same elements. Reordering or repeating elements changes nothing. Equal sets have equal counts, but equal counts do **not** make sets equal.`, v: eqTable, n: 'Two sets are equal when they have exactly the same elements. Writing them in another order, or repeating one, changes nothing. The table tests four descriptions against the set two, four, six. The last one has an extra element, eight, so it is a different set. Remember also that two sets can have the same number of elements without being equal.' }),
    sl('check', 'Quick check: the empty set', { b: 'Is the set that contains only the empty set an empty set?', chk: 'tf1', v: eqTable, n: 'Count the elements inside the outer brackets before you decide.' }),
    sl('example', 'Worked example 2: classify and compare', { b: r`Let $A = \{x \in \mathbb{Z} : x^2 - 2x - 8 = 0\}$ and $B = \{x \in \mathbb{N} : x^2 - 2x - 8 = 0\}$. Write both in roster form and compare.`, ul: [r`$x^2 - 2x - 8 = (x - 4)(x + 2)$, roots $4$ and $-2$`, r`$A = \{-2, 4\}$ has two elements`, r`$B = \{4\}$: $-2$ is not natural, so $B$ is a singleton`, r`$B \subset A$ and $B \ne A$`], v: table(['Set', 'Roster form', 'Elements', 'Type'], [['$A$', $(ex2A), `$${ex2A.size}$`, 'finite'], ['$B$', $(ex2B), `$${ex2B.size}$`, 'singleton']], 'Table comparing the two sets from the example: A is minus 2 and 4, with 2 elements; B is just 4, with 1 element, so B is a singleton that sits inside A.', 'Same equation, different universe, different set.'), n: 'Both sets come from the same equation, which factorises with roots four and minus two. The difference is the universe. Among the integers, both roots count, so the first set has two elements. Among the natural numbers, minus two is not allowed, so the second set is a singleton holding only four. It is inside the first set but not equal to it.' }),
    sl('concept', 'Subsets', { b: r`$B \subseteq A$ if every element of $B$ is in $A$. If also $B \ne A$, then $B$ is a **proper subset**: $B \subset A$. The empty set is a subset of every set, and every set is a subset of itself.`, v: nested.visual, n: 'A set B is a subset of A when every element of B is also in A. In the picture, the small circle inside the big one shows exactly this: four and eight belong to both. If B is not all of A, we call it a proper subset. Two facts to memorise: the empty set is a subset of every set, and every set is a subset of itself.' }),
    sl('concept', 'The power set', { b: r`The set of all subsets of $A$ is the **power set** $P(A)$. If $n(A) = n$, then $n(P(A)) = 2^n$, because each element is either in a subset or out of it.`, v: powerTable, n: 'List every subset of the three element set p, q, r, sorted by size. There is one with no elements, three with one element, three with two elements, and one with all three. That makes eight. The reason is simple: each element is either in or out, two choices for each, so three elements give two times two times two.' }),
    sl('diagram', 'Subsets double with each new element', { b: r`Subsets: $2^n$. Proper subsets: $2^n - 1$. Non-empty proper subsets: $2^n - 2$.`, v: powCount, n: 'Here is the doubling in numbers. A set with no elements has one subset, itself. Add one element and the count doubles to two, then four, eight, sixteen, thirty two, sixty four. Take away the set itself to count proper subsets, and take away the empty set as well to count the non-empty proper subsets. These three counts appear again and again.' }),
    sl('example', 'Worked example 3: counting with conditions', { b: r`How many subsets of $\{1, 2, 3, 4, 5, 6\}$ contain $2$ but not $5$?`, ul: ['$2$ must be in, $5$ must be out', r`The other four elements $1, 3, 4, 6$ are free`, r`**Answer.** $2^4 = 16$`], v: table(['Choice', 'Number of ways'], [['Forced in: $2$', '$1$'], ['Forced out: $5$', '$1$'], [r`Free: $1, 3, 4, 6$`, r`$2 \times 2 \times 2 \times 2 = 16$`], ['Total subsets', `$${ex3}$`]], 'Table for the worked example: element 2 is forced in, one way; element 5 is forced out, one way; elements 1, 3, 4, 6 are free, 2 times 2 times 2 times 2 ways; the total is 16 subsets.', 'Forced elements add no choice.'), n: 'When some elements are forced in or forced out, only the remaining elements give a choice. Here two must be in and five must be out, so each has just one way. The four other elements are each in or out, giving two to the fourth power, which is sixteen subsets. Listing all sixty four subsets by computer confirms the count.' }),
    sl('check', 'Quick check: counting subsets', { b: 'Fill in the number of subsets of a set with seven elements.', chk: 'fb1', v: powCount, n: 'Use the doubling rule with seven elements, and remember the empty set and the set itself both count.' }),
    sl('concept', 'Universal set', { b: r`Within one problem, every set is a subset of a fixed **universal set** $U$, drawn as a rectangle. Circles inside the rectangle represent subsets of $U$.`, v: univ.visual, n: 'In any problem, all the sets live inside one larger set called the universal set. We draw it as a rectangle and draw each set as a circle inside it. Here the universal set is the numbers one to nine and the circle holds the multiples of three. The numbers left outside the circle, but inside the rectangle, are the ones that are not multiples of three.' }),
    sl('concept', 'Intervals of real numbers', { b: r`Intervals are subsets of $\mathbb{R}$. A **square** bracket includes the end point; a **round** bracket excludes it. The symbol $\infty$ is not a number, so it always gets a round bracket.`, v: ivTable, n: 'Sets of real numbers between two end points are called intervals. A square bracket means the end point is included, and a round bracket means it is excluded. The symbol for infinity always gets a round bracket, because infinity is not a number you can reach. The table matches four descriptions with their interval notation.' }),
    sl('diagram', 'Intervals on the number line', { b: r`Filled circle: included. Open circle: excluded. Arrow: continues for ever.`, v: nl1, n: 'On the number line each interval is a thick line. A filled circle at an end point means the point is included, and an open circle means it is not. An arrow means the interval never stops. The four rows show an open interval, a closed interval, a half open interval, and one that runs for ever to the left.' }),
    sl('example', 'Worked example 4: integers in an interval', { b: r`How many integers lie in $(-1, 4)$, in $[-1, 4]$ and in $(-1, 4]$?`, ul: [r`$(-1, 4)$: $0, 1, 2, 3$ gives $4$`, r`$[-1, 4]$: $-1, 0, \dots, 4$ gives $6$`, r`$(-1, 4]$: $0, 1, \dots, 4$ gives $5$`], v: ivInts, n: 'The end points decide the count. In the open interval both ends are removed, leaving zero to three, which is four integers. In the closed interval both ends stay, giving minus one to four, which is six integers. The third interval drops minus one but keeps four, so it holds zero to four, five integers.' }),
    sl('check', 'Quick check: integers in an interval', { b: 'Count the integers in a half-open interval with a negative left end.', chk: 'm10', v: ivInts, n: 'Decide first which end point is included and which is not, then list the integers.' }),
    sl('summary', 'Summary', { ul: ['A set is a well-defined collection; roster form and set-builder form', 'Empty, singleton, finite, infinite; equal sets have the same elements', r`Subset, proper subset, universal set; $\varnothing \subseteq A$ always`, r`An $n$-element set has $2^n$ subsets`, 'Intervals: square bracket included, round bracket excluded'], v: summary1, n: 'To sum up. A set is a well defined collection, written by listing or by a rule. Sets can be empty, finite, infinite or equal. A subset has all its elements in the larger set, and a set with n elements has two to the power n subsets. Finally, intervals are sets of real numbers, with square brackets for included ends and round brackets for excluded ends.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: [r`**Roster form (1 to 2 marks):** solve the condition in the stated universe, then list every element once`, r`**Subset counts (1 to 3 marks):** state $2^n$ and the reason, fixing forced elements first`, r`**Intervals (1 to 2 marks):** each end-point bracket is marked; a wrong bracket loses the mark`, r`**Mistake:** calling $\{\varnothing\}$ the empty set`, r`**Mistakes:** dropping negative integers or $0$ when the universe is $\mathbb{Z}$; a square bracket beside $\infty$`], n: 'In the school examination, marks go to the roster form with every element listed once, to the power of two count with its reason, and to the correct bracket at each end of an interval. Common slips are calling a set that holds the empty set empty, forgetting negative integers and zero, and putting a square bracket next to infinity. Always solve the condition inside the universe the question names.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2, title: 'Sets — Part 2: Operations, laws and counting',
  goals: ['Find union, intersection, difference and complement from sets and Venn diagrams', 'Use the laws of set algebra, including De Morgan\'s laws', 'Operate on intervals of real numbers', 'Solve word problems on the number of elements in unions of two and three sets'],
  slides: [
    sl('title', 'Sets, Part 2: Combining sets', { b: 'Union, intersection, difference and complement build new sets from old ones.', v: vBase.visual, n: 'Welcome to part two. Two sets overlap in a Venn diagram: the factors of twenty four and the primes up to twelve. Two and three belong to both. You will combine sets in four ways, learn the laws that let you rewrite expressions, and use Venn diagrams to turn word problems into simple counting.' }),
    sl('concept', 'What you will be able to do', { ul: [r`Find $A \cup B$, $A \cap B$, $A - B$ and $A'$`, 'Read the regions of a **Venn diagram**', 'Use **commutative**, **distributive** and **De Morgan** laws', 'Operate on **intervals**', r`Count with $n(A \cup B)$ and $n(A \cup B \cup C)$`], v: summary2, n: 'Here are your goals for part two. You will compute the four operations from lists and diagrams, apply the laws of set algebra, combine intervals on the number line, and solve practical counting problems with the union formula for two sets and for three sets.' }),
    sl('concept', 'Union and intersection', { b: r`$A \cup B$: elements in $A$ **or** $B$ (or both). $A \cap B$: elements in **both**. If $A \cap B = \varnothing$ the sets are **disjoint**.`, v: vBase.visual, m: [r`A \cup B = \{x : x \in A \text{ or } x \in B\}, \quad A \cap B = \{x : x \in A \text{ and } x \in B\}`], n: 'The union of two sets collects everything that is in the first, or the second, or both. The intersection keeps only what is in both. In the diagram the union is all three coloured regions, and the intersection is the overlap, which holds two and three. Elements that appear in both sets are still listed only once in the union.' }),
    sl('diagram', 'Disjoint sets', { b: r`Sets with no common element are **disjoint**: their circles do not overlap and $M \cap P = \varnothing$.`, v: vDisj.visual, n: 'Sometimes two sets share nothing. The squares one, four, nine and the primes two, three, five, seven are an example. Their circles do not touch, and their intersection is the empty set. Disjoint sets matter in counting, because the size of their union is simply the sum of the two sizes.' }),
    sl('concept', 'Difference', { b: r`$A - B = \{x : x \in A \text{ and } x \notin B\}$. In general $A - B \ne B - A$.`, v: vBase.visual, m: [r`A - B = A \cap B'`], n: 'The difference of A and B keeps the elements of A that are not in B. Here A minus B is one, four, six, eight and twelve, the factors of twenty four that are not prime. B minus A is five, seven and eleven. The order matters: the two differences are different sets, one on each side of the overlap.' }),
    sl('concept', 'Complement', { b: r`$A' = U - A$: everything in $U$ that is **not** in $A$. Then $A \cup A' = U$ and $A \cap A' = \varnothing$.`, v: vComp.visual, n: 'The complement of a set is everything in the universal set that lies outside it, so it depends on the universal set you chose. For the factors of twenty four inside the numbers one to twelve, the complement is five, seven, nine, ten and eleven. A set and its complement together make the whole universal set, and they have nothing in common.' }),
    sl('check', 'Quick check: a difference as an intersection', { b: r`Which set equals $A \cap B'$?`, chk: 'm13', v: vBase.visual, n: 'Translate the symbols into words: in A, and not in B.' }),
    sl('example', 'Worked example 1: seven operations', { b: r`For $U = \{1, \dots, 12\}$, $A$ = factors of $24$ and $B$ = primes, find $A \cup B$, $A \cap B$, $A - B$, $B - A$, $A'$, $(A \cup B)'$ and $(A \cap B)'$.`, ul: ['Union: everything in either circle', r`Intersection: the overlap $\{2, 3\}$`, r`Differences: $A - B = \{1, 4, 6, 8, 12\}$, $B - A = \{5, 7, 11\}$`, 'Complements: from the numbers outside the regions'], v: opTable, n: 'Work from the diagram. The union lists ten numbers. The intersection is two and three. The two differences are one, four, six, eight, twelve on one side and five, seven, eleven on the other. The complement of the union is nine and ten, only two numbers, while the complement of the intersection contains everything except two and three. Every result is read straight from a region.' }),
    sl('concept', 'Laws of set algebra', { b: 'Union and intersection are **commutative** and **associative**, and each **distributes** over the other. Identity, complement and difference rules also hold. Each rule in the table was tested on every triple of subsets of a four-element set.', v: lawTable, n: 'Set operations obey laws much like those for numbers. Union and intersection can be swapped, regrouped, and each distributes over the other. There are identity laws with the empty set and the universal set, a complement law, and the useful rewrite of a difference as an intersection with a complement. The table lists nine rules, and each passed a test on every possible triple of subsets of a four element set.' }),
    sl('concept', 'De Morgan\'s laws', { b: r`$(A \cup B)' = A' \cap B'$ and $(A \cap B)' = A' \cup B'$. A complement swaps union and intersection.`, v: regTable, n: 'De Morgan laws tell you how a complement passes through a union or an intersection. Not in A or B means not in A and not in B. The table checks the four regions of a two circle diagram. Only the region outside both circles belongs to the complement of the union, and only that region belongs to both complements, so the two sets are the same.' }),
    sl('check', 'Quick check: complements and subsets', { b: r`If $A \subseteq B$, how do $A'$ and $B'$ compare?`, chk: 'tf3', v: regTable, n: 'Think about an element outside B. Can it be inside A?' }),
    sl('example', 'Worked example 2: verify a law', { b: r`With $U = \{1, \dots, 12\}$, $A$ = factors of $24$, $B$ = primes, verify $(A \cup B)' = A' \cap B'$.`, ul: [r`$A \cup B = \{1, 2, 3, 4, 5, 6, 7, 8, 11, 12\}$, so $(A \cup B)' = \{9, 10\}$`, r`$A' = \{5, 7, 9, 10, 11\}$, $B' = \{1, 4, 6, 8, 9, 10, 12\}$`, r`$A' \cap B' = \{9, 10\}$, equal ✓`], v: table(['Expression', 'Set'], [[r`$A \cup B$`, $(un(FA, PB))], [r`$(A \cup B)'$`, $(e2L)], [r`$A'$`, $(cp(e2U, FA))], [r`$B'$`, $(cp(e2U, PB))], [r`$A' \cap B'$`, $(e2R)]], 'Table verifying one De Morgan law: the union of A and B has ten elements, its complement is 9 and 10, and the intersection of the two complements is also 9 and 10.', 'Both sides give the same set.'), n: 'To verify a law with numbers, compute each side separately and compare. The union of A and B has ten elements, so its complement in one to twelve is just nine and ten. The complements of A and B are bigger sets, but their common part is again nine and ten. The two sides agree, as the law predicts.' }),
    sl('diagram', 'Intervals: union, intersection, difference', { b: r`$A = (-5, 1]$, $B = [-2, 4)$. Test every end point in **both** sets.`, v: nl2, n: 'Operations work on intervals as well. Take A, from minus five excluded to one included, and B, from minus two included to four excluded. The intersection runs from minus two to one with both ends included, because minus two is in A and one is in B. The union runs from minus five to four with both ends open. The difference A minus B stops just short of minus two.' }),
    sl('example', 'Worked example 3: interval end points', { b: r`For the intervals above, find $A \cap B$, $A \cup B$, $A - B$ and $B - A$.`, ul: [r`$A \cap B = [-2, 1]$: $-2 \in A$, $1 \in B$`, r`$A \cup B = (-5, 4)$: $-5 \notin A$, $4 \notin B$, no gap`, r`$A - B = (-5, -2)$: $-2 \in B$, so it is removed`, r`$B - A = (1, 4)$: $1 \in A$, so it is removed`], v: table(['Set', 'Interval', 'Left end', 'Right end'], [[r`$A \cap B$`, `$${ivTex(I_cap)}$`, 'included', 'included'], [r`$A \cup B$`, `$${ivTex(I_cup)}$`, 'excluded', 'excluded'], [r`$A - B$`, `$${ivTex(I_diff)}$`, 'excluded', 'excluded'], [r`$B - A$`, `$${ivTex(I_diff2)}$`, 'excluded', 'excluded']], 'Table of the four interval results with their end points: the intersection from minus 2 to 1 has both ends included; the union from minus 5 to 4, the difference A minus B from minus 5 to minus 2, and B minus A from 1 to 4 all have both ends excluded.', 'Decide every end point by testing it in both sets.'), n: 'The method never changes. Find the end points and test each one in both sets. Minus two is in A and in B, so it stays in the intersection. For the union, minus five is not in A and four is not in B, so both ends are open. For the difference, minus two belongs to B, so it is removed from A minus B, which therefore stays open there.' }),
    sl('concept', 'Counting two sets', { b: r`$n(A \cup B) = n(A) + n(B) - n(A \cap B)$. Also $n(A - B) = n(A) - n(A \cap B)$ and $n(A') = n(U) - n(A)$.`, v: vCount2.visual, m: [r`n(A \cup B) = n(A) + n(B) - n(A \cap B)`], n: 'To count a union, add the two sizes and subtract the overlap, because the overlap was counted twice. In the example, among one hundred fifty people, eighty five like tea and seventy two like coffee, and thirty like both. The diagram shows the four region counts, which add up to the total.' }),
    sl('example', 'Worked example 4: a word problem', { b: r`Of $150$ people, $85$ like tea, $72$ like coffee and $30$ like both. How many like at least one, only tea, neither?`, ul: [r`At least one: $85 + 72 - 30 = 127$`, r`Only tea: $85 - 30 = 55$`, r`Neither: $150 - 127 = 23$`], v: vCount2.visual, n: 'Start with the union formula: eighty five plus seventy two minus thirty gives one hundred twenty seven people who like at least one drink. Only tea is eighty five minus the overlap, which is fifty five. Those who like neither form the complement of the union: one hundred fifty minus one hundred twenty seven, twenty three. The diagram confirms all four regions.' }),
    sl('check', 'Quick check: a union count', { b: 'Count the books in both languages from the totals.', chk: 'm15', v: vCount2.visual, n: 'Every book is in at least one language, so the union equals the total. Then solve the union formula for the overlap.' }),
    sl('concept', 'Counting three sets', { b: r`$n(A \cup B \cup C) = n(A) + n(B) + n(C) - n(A \cap B) - n(B \cap C) - n(A \cap C) + n(A \cap B \cap C)$. Fill the Venn regions from the centre outwards.`, v: vCount3.visual, n: 'For three sets, add the three sizes, subtract the three pairwise overlaps, then add back the triple overlap, which was removed once too often. In the diagram, fill the centre first, then the pair only regions, then the single regions. The three circles together hold fifty three of sixty learners, and seven lie outside all of them.' }),
    sl('example', 'Worked example 5: three sets', { b: r`Using $n(A) = 29$, $n(B) = 25$, $n(C) = 25$, $n(A \cap B) = 10$, $n(B \cap C) = 9$, $n(A \cap C) = 11$, $n(A \cap B \cap C) = 4$ and $n(U) = 60$, find the learners in none of the sets and in exactly one set.`, ul: [r`At least one: $29 + 25 + 25 - 10 - 9 - 11 + 4 = 53$`, r`None: $60 - 53 = 7$`, r`Only $A$: $29 - 6 - 7 - 4 = 12$ with pair-only counts $6, 5, 7$`, r`Exactly one: $12 + 10 + 9 = 31$`], v: table(['Region', 'Count'], [['Only $A$', `$${vCount3.regions['100'].length}$`], ['Only $B$', `$${vCount3.regions['010'].length}$`], ['Only $C$', `$${vCount3.regions['001'].length}$`], ['Exactly one set', `$${vCount3.regions['100'].length + vCount3.regions['010'].length + vCount3.regions['001'].length}$`], ['None', `$${vCount3.regions['000'].length}$`]], 'Table of region counts for the three-set example: only A 12, only B 10, only C 9, so exactly one set holds 31 learners, and 7 learners lie in none of the sets.', 'Add the single-set regions for exactly one.'), n: 'First the union: add the three sizes, subtract the three pair overlaps, add the triple overlap, and you get fifty three. So seven learners are in none of the sets. To find those in exactly one set, subtract from each size the parts shared with the other sets, adding the triple back once. That gives twelve, ten and nine, which total thirty one.' }),
    sl('summary', 'Summary', { ul: [r`$A \cup B$, $A \cap B$, $A - B$, $A'$ read from Venn regions`, 'Laws: commutative, associative, distributive, identity, complement, De Morgan', 'Intervals: test every end point in both sets', r`$n(A \cup B) = n(A) + n(B) - n(A \cap B)$`, 'Three sets: singles, minus pairs, plus triple'], v: summary2, n: 'To sum up. The four operations come straight from Venn regions. The laws, especially De Morgan, let you rewrite expressions. On intervals, test each end point in both sets. For counting, add the sizes and subtract the overlap, and for three sets add back the triple overlap at the end.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: [r`**Verify a law (2 to 3 marks):** compute both sides separately, then state that they are equal`, r`**Prove an identity (2 to 5 marks):** two inclusions, each with a general element $x$`, '**Intervals:** one mark for each correct end-point decision', '**Word problems (3 to 5 marks):** formula or Venn diagram, then each region or total', r`**Mistakes:** treating $A - B$ as $B - A$; counting the overlap twice; taking a complement in the wrong universal set`], n: 'In the school examination, verification questions give a mark for each side computed and one for the conclusion. Proofs of identities need both inclusions, written with a general element. Interval answers are marked end point by end point. Word problems earn marks for the method and for each region or total. Common slips are swapping the two differences, miscounting the overlap, and taking a complement in the wrong universal set.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'isc-11-mathematics-ch01', version: 1, title: 'Sets — chapter notes', language: 'en',
  sections: [
    { heading: '1. Sets and their representations', body_md: r`A **set** is a well-defined collection of objects; the objects are its **elements**. $a \in A$ means $a$ belongs to $A$.\n\n- **Roster form:** list the elements once each, e.g. $\{12, 24, 36, 48\}$.\n- **Set-builder form:** give a rule, e.g. $\{x \in \mathbb{N} : x \text{ is a two-digit multiple of } 12\}$.\n\nStandard sets: $\mathbb{N}$, $\mathbb{W}$, $\mathbb{Z}$, $\mathbb{Q}$, $\mathbb{R}$, each inside the next. Solve a set-builder condition inside the stated universe (negative integers and $0$ count in $\mathbb{Z}$).`, key_terms: [{ term: 'Set', definition_md: 'A well-defined collection: a clear rule settles membership.' }, { term: 'Element', definition_md: r`An object in a set; $a \in A$.` }, { term: 'Roster form', definition_md: 'The set written by listing its elements once each.' }, { term: 'Set-builder form', definition_md: 'The set written by a rule its elements satisfy.' }], formulas: [{ latex: r`\{x \in \mathbb{N} : x < 5\} = \{1, 2, 3, 4\}`, label: 'Rule to roster' }], visual: rbTable, visuals: [wd, chain], topic_ids: [topic(1)] },
    { heading: '2. Empty, finite, infinite and equal sets', body_md: r`- **Empty set** $\varnothing$: no element. $\{\varnothing\}$ is **not** empty; it has one element.\n- **Singleton:** exactly one element.\n- **Finite:** counting ends; $n(A)$ is the number of elements.\n- **Infinite:** counting never ends.\n- **Equal sets:** exactly the same elements. Order and repeats do not matter; equal counts do not make equal sets.\n\nThe same equation can give different sets in different universes: $x^2 - 2x - 8 = 0$ gives $\{-2, 4\}$ in $\mathbb{Z}$ but $\{4\}$ in $\mathbb{N}$.`, key_terms: [{ term: 'Empty set', definition_md: r`The set with no elements, $\varnothing$.` }, { term: 'Finite set', definition_md: 'A set whose elements can be counted to the end.' }, { term: 'Equal sets', definition_md: 'Sets with exactly the same elements.' }], formulas: [{ latex: r`A = B \iff A \subseteq B \text{ and } B \subseteq A`, label: 'Equality' }], visual: typesTable, visuals: [eqTable], topic_ids: [topic(1)] },
    { heading: '3. Subsets, power set and universal set', body_md: r`$B \subseteq A$ if every element of $B$ is in $A$; $B \subset A$ if also $B \ne A$ (**proper** subset). $\varnothing \subseteq A$ and $A \subseteq A$ always.\n\nThe **power set** $P(A)$ is the set of all subsets. If $n(A) = n$: subsets $2^n$; proper subsets $2^n - 1$; non-empty proper subsets $2^n - 2$. Forcing $k$ elements in or out leaves $2^{n-k}$ subsets.\n\nThe **universal set** $U$ contains every set of the discussion; it is the rectangle of a Venn diagram.`, key_terms: [{ term: 'Subset', definition_md: r`$B \subseteq A$: every element of $B$ is in $A$.` }, { term: 'Power set', definition_md: r`$P(A)$: the set of all subsets of $A$.` }, { term: 'Universal set', definition_md: r`The set $U$ of which all sets under discussion are subsets.` }], formulas: [{ latex: r`n(P(A)) = 2^{n}`, label: 'Number of subsets' }], visual: powerTable, visuals: [nested.visual, powCount], topic_ids: [topic(2)] },
    { heading: '4. Intervals of real numbers', body_md: r`Intervals are subsets of $\mathbb{R}$. $(a, b)$ excludes both ends; $[a, b]$ includes both; $[a, b)$ and $(a, b]$ include one. $(a, \infty)$ and $(-\infty, b]$ are unbounded. $\infty$ is never included.\n\nOn the number line: filled circle = included, open circle = excluded.\n\nIntegers in an interval depend on the ends: $(-1, 4)$ has $4$, $[-1, 4]$ has $6$, $(-1, 4]$ has $5$.`, key_terms: [{ term: 'Open interval', definition_md: r`$(a, b)$: both end points excluded.` }, { term: 'Closed interval', definition_md: r`$[a, b]$: both end points included.` }, { term: 'Half-open interval', definition_md: r`$[a, b)$ or $(a, b]$: one end point included.` }], formulas: [{ latex: r`[a, b] = \{x \in \mathbb{R} : a \le x \le b\}`, label: 'Closed interval' }], visual: nl1, visuals: [ivTable, ivInts], topic_ids: [topic(2)] },
    { heading: '5. Venn diagrams and operations', body_md: r`- **Union** $A \cup B$: in $A$ or $B$ (or both).\n- **Intersection** $A \cap B$: in both. **Disjoint** if $A \cap B = \varnothing$.\n- **Difference** $A - B$: in $A$, not in $B$; in general $A - B \ne B - A$.\n- **Complement** $A' = U - A$.\n\nIn a Venn diagram, label the regions: only $A$, both, only $B$, outside. For intervals, test every end point in both sets: $(-5, 1] \cap [-2, 4) = [-2, 1]$ and $(-5, 1] \cup [-2, 4) = (-5, 4)$.`, key_terms: [{ term: 'Union', definition_md: 'All elements of either set, each listed once.' }, { term: 'Intersection', definition_md: 'The elements common to both sets.' }, { term: 'Complement', definition_md: r`$A' = U - A$, the elements of $U$ not in $A$.` }], formulas: [{ latex: r`A - B = A \cap B'`, label: 'Difference as intersection' }], visual: vBase.visual, visuals: [vDisj.visual, vComp.visual, opTable, nl2], topic_ids: [topic(3)] },
    { heading: '6. Laws of set algebra and De Morgan', body_md: r`- **Commutative:** $A \cup B = B \cup A$, $A \cap B = B \cap A$.\n- **Associative:** $(A \cup B) \cup C = A \cup (B \cup C)$, and the same for $\cap$.\n- **Distributive:** $A \cap (B \cup C) = (A \cap B) \cup (A \cap C)$, $A \cup (B \cap C) = (A \cup B) \cap (A \cup C)$.\n- **De Morgan:** $(A \cup B)' = A' \cap B'$, $(A \cap B)' = A' \cup B'$.\n- **Identity and complement:** $A \cup \varnothing = A$, $A \cap U = A$, $A \cup A' = U$, $A \cap A' = \varnothing$; also $(A')' = A$.\n\nTo **verify** a law, compute both sides for the given sets. To **prove** an identity, show each side is a subset of the other using a general element $x$.`, key_terms: [{ term: 'De Morgan\'s laws', definition_md: 'A complement turns a union into an intersection of complements and the reverse.' }, { term: 'Distributive law', definition_md: 'Each of union and intersection distributes over the other.' }], formulas: [{ latex: r`(A \cup B)' = A' \cap B', \qquad (A \cap B)' = A' \cup B'`, label: 'De Morgan' }], visual: lawTable, visuals: [regTable], topic_ids: [topic(3)] },
    { heading: '7. Counting with sets', body_md: r`$n(A \cup B) = n(A) + n(B) - n(A \cap B)$, $n(A - B) = n(A) - n(A \cap B)$, $n(A') = n(U) - n(A)$. For disjoint sets, $n(A \cup B) = n(A) + n(B)$.\n\nThree sets: $n(A \cup B \cup C) = n(A) + n(B) + n(C) - n(A \cap B) - n(B \cap C) - n(A \cap C) + n(A \cap B \cap C)$.\n\nMethod: draw a Venn diagram and fill the **innermost region first**, then work outwards. Check that the regions add up to $n(U)$.`, key_terms: [{ term: 'n(A)', definition_md: 'The number of elements of the finite set $A$.' }], formulas: [{ latex: r`n(A \cup B) = n(A) + n(B) - n(A \cap B)`, label: 'Two sets' }], visual: vCount2.visual, visuals: [vCount3.visual], topic_ids: [topic(3)] },
  ],
  exam_tips_md: r`**How marks are awarded** (school examination, Paper I: Sets and Functions together carry 18 of the 80 marks)\n- *Objective items (1 mark each):* one mark for the correct option, so read every option.\n- *Roster and set-builder (2 marks):* solve the condition in the stated universe, then list each element once.\n- *Subset counts (2 to 3 marks):* $2^n$ with the reason; forced elements first.\n- *Verify a law (3 marks):* each side computed separately, then the conclusion.\n- *Prove an identity (2 to 3 marks):* each inclusion with a general $x$, then the conclusion.\n- *Intervals (2 to 3 marks):* one mark for each correct end-point decision.\n- *Long answer (5 marks, set in parts):* word problems and multi-part verifications; show the formula or the Venn regions.\n\n**Common mistakes**\n1. Calling $\{\varnothing\}$ the empty set.\n2. Leaving out negative integers or $0$ when the universe is $\mathbb{Z}$.\n3. Treating $A - B$ as $B - A$.\n4. Writing a square bracket next to $\infty$.\n5. Counting the overlap twice in $n(A \cup B)$.\n6. Taking a complement in the wrong universal set.\n7. Proving a set identity with one example instead of a general element.\n8. Forgetting that the empty set and the set itself are both subsets.`,
  status: 'draft', provenance: d1.provenance,
};

